channel.ExchangeDeclare("order-commands", ExchangeType.Direct);
channel.QueueDeclare("order-processing", durable: true, exclusive: false, autoDelete: false, null);
channel.QueueBind("order-processing", "order-commands", "order.create");

// Multiple consumers share the same queue
// RabbitMQ round-robins messages among them
channel.BasicPublish(exchange: "order-commands", routingKey: "order.create", basicProperties: null, body: body);

// Create topic
await adminClient.CreateTopicAsync("events", new CreateTopicOptions());

// Subscription A: only order events
await adminClient.CreateSubscriptionAsync("events", "order-subscription",
    new CreateSubscriptionOptions("events", "order-sub")
    {
        RuleOptions = new RuleOptions
        {
            Filter = new SqlRuleFilter("eventType = 'OrderCreated'")
        }
    });

// Subscription B: only payment events
await adminClient.CreateSubscriptionAsync("events", "payment-subscription",
    new CreateSubscriptionOptions("events", "payment-sub")
    {
        RuleOptions = new RuleOptions
        {
            Filter = new SqlRuleFilter("eventType = 'PaymentProcessed'")
        }
    });
